-- the raw topic also carries the parts of multi-message transactions (x-event-type): not unified events
CREATE MATERIALIZED VIEW realy.events_mv TO realy.events_raw AS
SELECT
  arrayElement(_headers.value, indexOf(_headers.name, 'x-run-id')) AS run_id,
  `event_id`,
  `event_time_us`,
  arrayElement(['UNSPECIFIED', 'CARD_PURCHASE', 'ATM_WITHDRAWAL', 'TRANSFER', 'CARD_REFUND'], toInt32(payment_type) + 1) AS `payment_type`,
  `customer_id`,
  `account_id`,
  `card_id`,
  toString(card_type) AS `card_type`,
  `amount_minor`,
  `currency`,
  `amount_usd_minor`,
  `merchant_id`,
  `mcc`,
  `merchant_country`,
  `terminal_id`,
  arrayElement(['UNSPECIFIED', 'POS', 'ECOM', 'ATM', 'MOTO', 'IN_APP', 'ONLINE_BANKING'], toInt32(channel) + 1) AS `channel`,
  arrayElement(['UNSPECIFIED', 'CHIP', 'CONTACTLESS', 'MAGSTRIPE', 'MANUAL', 'WALLET_TOKEN', 'ECOM_3DS', 'ECOM_NON_3DS', 'CREDENTIAL_ON_FILE', 'BANK_APP'], toInt32(entry_mode) + 1) AS `entry_mode`,
  `card_present`,
  `lat`,
  `lon`,
  `device_id`,
  `ip_v4`,
  `ip_country`,
  `ip_asn`,
  `payee_id`,
  `cvv_match`,
  `avs_match`,
  `recurring`,
  `credit_limit_usd`,
  `three_ds`,
  `pin_verified`,
  `cryptogram_valid`,
  `scheme_score`,
  `card_info.id`,
  `card_info.bin`,
  `card_info.bin_country`,
  `card_info.status`,
  `card_info.network`,
  `card_info.tokenized`,
  `card_info.wallet`,
  `card_info.issued_at_us`,
  `account_info.id`,
  `account_info.type`,
  `account_info.balance_usd_minor`,
  `account_info.age_days`,
  `merchant_info.id`,
  `merchant_info.name`,
  `merchant_info.mcc`,
  `merchant_info.address.country`,
  `merchant_info.address.city`,
  `merchant_info.address.postcode`,
  `merchant_info.risk_tier`,
  `device_info.id`,
  `device_info.os`,
  `device_info.app_version`,
  `device_info.emulator`,
  `device_info.rooted`,
  `device_info.risk_score`,
  `payee_info.id`,
  `payee_info.bank_country`,
  `payee_info.new_payee`,
  `payee_info.name_match`,
  `authentication.three_ds`,
  `authentication.attempts`,
  `authentication.method`,
  `authentication.sca_exempt`,
  `account_info.flags`,
  `items.sku`,
  `items.qty`,
  `items.amount_usd_minor`,
  `items.category`,
  `attributes`
FROM realy.events_queue WHERE length(_error) = 0 AND indexOf(_headers.name, 'x-event-type') = 0;

